import numpy as np
import pandas as pd

class NumpyExtensionArray:
    def __init__(self, array):
        self.array = array

    def take(self, indices, allow_fill=False):
        # Initialize fill_value based on the dtype of the array
        fill_value = np.nan if self.array.dtype != np.bool_ else pd.NA

        # Use pandas take function which correctly handles allow_fill=True with negative indices
        result = pd.Series(self.array).take(indices, allow_fill=allow_fill, fill_value=fill_value).to_numpy()

        # Ensure the dtype of the result is as expected
        if self.array.dtype == np.bool_:
            result = result.astype(object)
        else:
            result = result.astype(np.float64)

        return result
